changeSet.sql:
INSERT INTO jhi_user (id, login, password_hash, full_name, email, activated, created_by, created_date, last_modified_by, last_modified_date, department_id) SELECT COALESCE((SELECT MAX(id) FROM jhi_user), 0) + 1, 'manager@company.com', '$2a$10$CDmKhVpPz7.5I4Mrm6sVreAINrmDhCJrCL3ao2FxMxUCBRVZbwglO', 'Manager Demo', 'manager@company.com', TRUE, 'system', NOW(), 'system', NOW(), (SELECT id FROM department ORDER BY id LIMIT 1);
INSERT INTO jhi_user_authority (user_id, authority_name) SELECT id, 'ROLE_MANAGER' FROM jhi_user WHERE login = 'manager@company.com';
INSERT INTO jhi_user_authority (user_id, authority_name) SELECT id, 'ROLE_USER' FROM jhi_user WHERE login = 'manager@company.com';

INSERT INTO jhi_user (id, login, password_hash, full_name, email, activated, created_by, created_date, last_modified_by, last_modified_date, department_id) SELECT COALESCE((SELECT MAX(id) FROM jhi_user), 0) + 1, 'staff@company.com', '$2a$10$CDmKhVpPz7.5I4Mrm6sVreAINrmDhCJrCL3ao2FxMxUCBRVZbwglO', 'Staff Demo', 'staff@company.com', TRUE, 'system', NOW(), 'system', NOW(), (SELECT id FROM department ORDER BY id LIMIT 1);
INSERT INTO jhi_user_authority (user_id, authority_name) SELECT id, 'ROLE_STAFF' FROM jhi_user WHERE login = 'staff@company.com';
INSERT INTO jhi_user_authority (user_id, authority_name) SELECT id, 'ROLE_USER' FROM jhi_user WHERE login = 'staff@company.com';
SELECT setval( 'sequence_generator', GREATEST( (SELECT COALESCE(MAX(id), 0) FROM jhi_user), (SELECT last_value FROM sequence_generator) ) );
